package com.campusconnect.rag;
import com.campusconnect.user.UserRepository; import com.campusconnect.audit.AsyncAuditService; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.security.Principal; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/documents") public class DocumentController {private final RagService rag;private final UserRepository users;private final AsyncAuditService audit;public DocumentController(RagService r,UserRepository u,AsyncAuditService audit){rag=r;users=u;this.audit=audit;}
@GetMapping public List<Map<String,Object>> list(){return rag.list();}
@PostMapping(consumes="multipart/form-data") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public Map<String,Object> upload(@RequestParam String title,@RequestParam("file") MultipartFile file,Principal p)throws Exception{String name=Objects.requireNonNullElse(file.getOriginalFilename(),"upload.txt");String type=Objects.requireNonNullElse(file.getContentType(),"");if(!(type.startsWith("text/")||name.toLowerCase(Locale.ROOT).endsWith(".txt")||name.toLowerCase(Locale.ROOT).endsWith(".md")||name.toLowerCase(Locale.ROOT).endsWith(".csv")))throw new IllegalArgumentException("Upload a text, Markdown, or CSV document. PDF/DOCX parsing is not enabled in this build.");var u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();var d=rag.ingest(title,name,new String(file.getBytes(),StandardCharsets.UTF_8),u);audit.record("DOCUMENT_UPLOAD",p.getName(),"documentId="+d.getId()+", title="+title);return Map.of("id",d.getId(),"title",d.getTitle(),"originalName",d.getOriginalName(),"uploadedAt",d.getUploadedAt());}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id,Principal p){rag.delete(id);audit.record("DOCUMENT_DELETE",p.getName(),"documentId="+id);}
@GetMapping("/search") public List<Map<String,Object>> search(@RequestParam String q){return rag.retrieve(q,5);}}
